class Solution:
    def minimumOperationsToMakeKPeriodic(self, word: str, k: int) -> int:
        blocks = [word[i:i+k] for i in range(0, len(word), k)]
        best = 0
        for b in blocks:
            c = sum(1 for x in blocks if x == b)
            best = max(best, c)
        return len(blocks) - best

