class Solution {
public:
    int minimumOperationsToMakeKPeriodic(string word, int k) {
        int m = word.size() / k;
        int best = 0;
        for (int i = 0; i < m; i++) {
            int c = 0;
            for (int j = 0; j < m; j++)
                if (word.compare(i*k, k, word, j*k, k) == 0) c++;
            best = max(best, c);
        }
        return m - best;
    }
};

