class Solution {
    public int minimumOperationsToMakeKPeriodic(String word, int k) {
        int m = word.length() / k;
        int best = 0;
        for (int i = 0; i < m; i++) {
            String a = word.substring(i * k, i * k + k);
            int c = 0;
            for (int j = 0; j < m; j++)
                if (word.substring(j * k, j * k + k).equals(a)) c++;
            best = Math.max(best, c);
        }
        return m - best;
    }
}

